// Stand-ins for the few Home Assistant frontend elements the Moments cards use,
// so the real cards render on a plain web page.
// "virtual:mdi" is generated by site/build.mjs: only the mdi icons the cards,
// examples and site actually name, so the bundle stays small.
import { PATHS } from "virtual:mdi";

const FALLBACK = PATHS["mdi:help-circle-outline"] ?? "";

class HaCard extends HTMLElement {
  constructor() {
    super();
    const r = this.attachShadow({ mode: "open" });
    r.innerHTML = `<style>:host{display:block;position:relative;box-sizing:border-box;background:var(--ha-card-background,var(--card-background-color,#fff));border-radius:var(--ha-card-border-radius,12px);border:var(--ha-card-border-width,1px) solid var(--ha-card-border-color,var(--divider-color,#e0e0e0));box-shadow:var(--ha-card-box-shadow,none);color:var(--primary-text-color);backdrop-filter:var(--ha-card-backdrop-filter,none);-webkit-backdrop-filter:var(--ha-card-backdrop-filter,none)}</style><slot></slot>`;
  }
}

class HaIcon extends HTMLElement {
  _icon = "";
  static get observedAttributes() {
    return ["icon"];
  }
  attributeChangedCallback(_n: string, _o: string, v: string) {
    this.icon = v;
  }
  set icon(v: string) {
    this._icon = v;
    this.draw();
  }
  get icon() {
    return this._icon;
  }
  connectedCallback() {
    this.draw();
  }
  draw() {
    if (!this.shadowRoot) this.attachShadow({ mode: "open" });
    const p = PATHS[this._icon] ?? FALLBACK;
    this.shadowRoot!.innerHTML = `<style>:host{display:inline-flex;align-items:center;justify-content:center;width:var(--mdc-icon-size,24px);height:var(--mdc-icon-size,24px);vertical-align:middle}svg{width:100%;height:100%;fill:currentColor}</style><svg viewBox="0 0 24 24" aria-hidden="true"><path d="${p}"/></svg>`;
  }
}

const DOMAIN_ICONS: Record<string, string> = {
  light: "mdi:lightbulb",
  switch: "mdi:power-plug",
  fan: "mdi:fan",
  cover: "mdi:blinds-horizontal",
  lock: "mdi:lock",
  climate: "mdi:thermostat",
  media_player: "mdi:television",
  binary_sensor: "mdi:checkbox-blank-circle-outline",
  sensor: "mdi:eye",
};

class HaStateIcon extends HaIcon {
  set stateObj(e: any) {
    const domain = String(e?.entity_id ?? "").split(".")[0];
    this.icon = e?.attributes?.icon ?? DOMAIN_ICONS[domain] ?? "mdi:help-circle-outline";
  }
}

for (const [tag, cls] of [
  ["ha-card", HaCard],
  ["ha-icon", HaIcon],
  ["ha-state-icon", HaStateIcon],
] as const) {
  if (!customElements.get(tag)) customElements.define(tag, cls);
}

// The cards navigate with history.pushState, as inside Home Assistant. On the site that
// would change the page URL, so turn it into an event the demos can act on instead.
const realPush = history.pushState.bind(history);
history.pushState = (data: any, unused: string, url?: string | URL | null) => {
  if (url == null || String(url).startsWith("#")) return realPush(data, unused, url);
  window.dispatchEvent(new CustomEvent("moments-navigate", { detail: { path: String(url) } }));
};
